784	{
785	  uint16_t refcolumn = 1, i = 0;
786	  uint32_t size = 0, xsize = 0;
787	  uint8_t  *ptr = Text;
788	
789	  /* Get the text size */
790	  while (*ptr++) size ++ ;
791	
792	  /* Characters number per line */
793	  xsize = (BSP_LCD_GetXSize()/DrawProp[ActiveLayer].pFont->Width);
794	
795	  switch (Mode)
796	  {
797	  case CENTER_MODE:
798	    {
799	      refcolumn = Xpos + ((xsize - size)* DrawProp[ActiveLayer].pFont->Width) / 2;
800	      break;
801	    }
802	  case LEFT_MODE:
803	    {
804	      refcolumn = Xpos;
805	      break;
806	    }
807	  case RIGHT_MODE:
808	    {
809	      refcolumn = - Xpos + ((xsize - size)*DrawProp[ActiveLayer].pFont->Width);
810	      break;
811	    }
812	  default:
813	    {
814	      refcolumn = Xpos;
815	      break;
816	    }
817	  }
818	
819	  /* Check that the Start column is located in the screen */
820	  if ((refcolumn < 1) || (refcolumn >= 0x8000))
821	  {
822	    refcolumn = 1;
823	  }
824

825	  /* Send the string character by character on LCD */
826	  while ((*Text != 0) & (((BSP_LCD_GetXSize() - (i*DrawProp[ActiveLayer].pFont->Width)) & 0xFFFF) >= DrawProp[ActiveLayer].pFont->Width))
827	  {
