829	    BSP_LCD_DisplayChar(refcolumn, Ypos, *Text);
830	    /* Decrement the column position by 16 */
831	    refcolumn += DrawProp[ActiveLayer].pFont->Width;
832	
833	    /* Point on the next character */
834	    Text++;
835	    i++;
836	  }
